package org.sleepwell.app;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;

/** Real isolated alarm JSON/SQLite/portable data with injected scheduler; no alarm service or output. */
public final class AlarmTimingStorageTest {
    @Test public void absentLegacyTimingIsUnchangedAndExplicitPolicySurvivesInactivePortableRestore()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){Alarm original=f.load();String unchanged=original.json().toString();assertEquals(AlarmTiming.DEFAULT,original.timing);assertFalse(original.json().has("timing"));assertEquals(unchanged,Alarm.read(original.json()).json().toString());Alarm draft=Alarm.read(original.json());draft.timing=new AlarmTiming(60,2,3,15);AlarmSkips.edit(f.c,store,draft,original,true);assertEquals(draft.timing,f.load().timing);JSONObject portable=store.backup();Backup.validate(portable);Backup.restoreData(store,portable);Alarm restored=store.alarm(1);assertFalse(restored.enabled);assertEquals(draft.timing,restored.timing);assertEquals(original.days,restored.days);assertEquals(original.hour,restored.hour);assertEquals(original.awakeCheck,restored.awakeCheck);assertEquals(original.challenge,restored.challenge);}}
    @Test public void strictMalformedTimingIsPreservedForReviewAndRejectedBeforeReplacingData()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){JSONObject valid=AlarmTimingJson.encode(new AlarmTiming(60,2,3,15));for(Object bad:new Object[]{JSONObject.NULL,"default",new JSONObject(),new JSONObject(valid.toString()).put("backupSeconds",60.5),new JSONObject(valid.toString()).put("backupRepeats",6),new JSONObject(valid.toString()).put("backupGapMinutes",0),new JSONObject(valid.toString()).put("timeoutMinutes",121),new JSONObject(valid.toString()).put("timeoutMinutes","15"),new JSONObject(valid.toString()).put("surprise",1)}){JSONObject raw=f.load().json().put("timing",bad);Alarm invalid=Alarm.read(raw);assertTrue(invalid.timingInvalid);assertEquals(AlarmTiming.DEFAULT,invalid.timing);assertTrue(invalid.json().has("timing"));assertThrows(IllegalArgumentException.class,()->new AlarmDefaults(invalid));JSONObject portable=store.backup();portable.getJSONArray("alarms").put(0,raw);String before=BackupFingerprint.read(store);assertThrows(JSONException.class,()->Backup.restoreData(store,portable));assertEquals(before,BackupFingerprint.read(store));}}}
    @Test public void templatesTransferImmutableTimingWithoutScheduleOrRuntimeAuthority()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture()){Alarm original=f.load();original.timing=new AlarmTiming(300,5,15,120);AlarmDefaults snapshot=AlarmDefaultsJson.decode(AlarmDefaultsJson.encode(new AlarmDefaults(original)));original.timing=AlarmTiming.DEFAULT;Alarm fresh=snapshot.create(9);assertEquals(new AlarmTiming(300,5,15,120),fresh.timing);assertFalse(fresh.enabled);assertTrue(fresh.days.isEmpty());assertEquals(7,fresh.hour);assertEquals(AlarmTiming.DEFAULT,f.load().timing);AlarmLifetime policy=new AlarmLifetime(fresh,"private",new AlarmLifetime.Owner(){public boolean current(String run){return true;}public boolean backupIfCurrent(String run,boolean backup){return true;}public boolean timeoutIfCurrent(String run){return true;}});assertEquals(AlarmLifetime.Phase.EXPIRED,policy.phase(120*60000L,true));}}
}
